import numpy as np

def step_function(x):
    return np.where(x > 0, 1.0, 0.0)

def sigmoid(x):
    return 1 / (1 + np.exp(-x))

def numerical_gradient(func, x, epsilon=1e-5):
    return (func(x + epsilon) - func(x - epsilon)) / (2 * epsilon)

test_points = np.array([-2.0, -0.5, 0.5, 2.0])

print("Step function gradients (numerically estimated):")
for x in test_points:
    gradient = numerical_gradient(step_function, x)
    print(f"  At x={x}: output={step_function(x):.1f}, gradient={gradient:.6f}")

print("\nSigmoid gradients (numerically estimated):")
for x in test_points:
    gradient = numerical_gradient(sigmoid, x)
    print(f"  At x={x}: output={sigmoid(x):.4f}, gradient={gradient:.6f}")

print("\nNotice the step function's gradient is essentially zero everywhere, while sigmoid's gradient is genuinely usable")
